import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        int[] a = new int[n];
        int limit = 1;
        for (int i = 0; i < n; i++) {
            a[i] = nextInt();
            limit = Math.max(limit, a[i]);
        }
        // Sieve Euler's totient: for each prime p, phi[x] -= phi[x] / p on its multiples.
        int[] phi = new int[limit + 1];
        for (int i = 0; i <= limit; i++) phi[i] = i;
        for (int p = 2; p <= limit; p++)
            if (phi[p] == p)
                for (int x = p; x <= limit; x += p) phi[x] -= phi[x] / p;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(' ');
            sb.append(phi[a[i]]);
        }
        sb.append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	a := make([]int, n)
	limit := 1
	for i := range a {
		a[i] = int(nextInt())
		limit = max(limit, a[i])
	}
	// Sieve Euler's totient: for each prime p, phi[x] -= phi[x] / p on its multiples.
	phi := make([]int, limit+1)
	for i := range phi {
		phi[i] = i
	}
	for p := 2; p <= limit; p++ {
		if phi[p] == p {
			for x := p; x <= limit; x += p {
				phi[x] -= phi[x] / p
			}
		}
	}
	out := make([]byte, 0, 8*n)
	for i, v := range a {
		if i > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, int64(phi[v]), 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
